import React, { useState, useEffect } from "react";
import { Link, useLoaderData, useParams } from "@tanstack/react-router";
import { Helmet } from "react-helmet";
import axios from "axios";
// Components
import BlogCategoriesCard from "./BlogCategoriesCard";
import BlogItemsDisplay from "./BlogItemsDisplay";
import BlogsList from "./BlogsList";
import ShareProduct from "../ShareProduct/ShareProduct";

// Data
import listdData from "./listdData.json";
const Blog = () => {
	useEffect(() => {
		window.scrollTo(0, 0);
	}, []);

	const params = useParams({ strict: false });
	const loaderData = useLoaderData({ strict: false });
	const rootData = useLoaderData({ from: '__root__' });
	const [category, setCategory] = useState(rootData?.categories || []);
	const [readEnabled, setReadEnabled] = useState(false);
	const [blogs, setBlogs] = useState(loaderData?.blogs || []);
	const [selectedBlog, setSelectedBlog] = useState(loaderData?.selectedBlog || blogs[0]);
	const [error, setError] = useState(null);

	useEffect(() => {
		// console.log("Blog Component: loaderData received:", loaderData);
		if (loaderData) {
			if (loaderData.blogs) {
				setBlogs(loaderData.blogs);
				if (loaderData.blogs.length === 0) {
					// Fallback if loader didn't fetch or returned empty
					axios.get((process.env.REACT_APP_SERVER || "").replace(/\/$/, "") + "/api/blogdata")
						.then(res => {
							const fetchedBlogs = Array.isArray(res.data?.data) ? res.data.data : [];
							setBlogs(fetchedBlogs);
							if (!selectedBlog && fetchedBlogs.length > 0) {
								const normalizedParam = params.link?.replace(/\/$/, '').toLowerCase();
								setSelectedBlog(fetchedBlogs.find(b => b.blogLink?.replace(/\/$/, '').toLowerCase() === normalizedParam) || fetchedBlogs[0]);
							}
						})
						.catch(err => {
							console.error("Failed to fetch fallback blogs", err);
							setError("Failed to load blogs. Please check your connection.");
						});
				}
			}
			if (loaderData.selectedBlog !== undefined) {
				setSelectedBlog(loaderData.selectedBlog || loaderData.blogs?.[0]);
			}
		}
	}, [loaderData, params.link, selectedBlog]);

	useEffect(() => {
		if (rootData?.categories && rootData.categories.length > 0) {
			setCategory(rootData.categories);
		} else if (category.length === 0) {
			axios.get((process.env.REACT_APP_SERVER || "").replace(/\/$/, "") + "/api/categorySideBar/")
				.then((res) => {
					if (res.data && res.data.data) {
						setCategory(res.data.data);
					}
				})
				.catch(err => console.error("Error fetching categories", err));
		}
	}, [rootData, category.length]);
	// useEffect removed: fetching moved to route loader
	return (
		<>
			<Helmet>
				<meta charSet="utf-8" />
				<title>{selectedBlog?.title || "Kijeka Blog"}</title>

				<meta name="title" content={selectedBlog?.title || "Kijeka Blog"}></meta>
				<meta name="description" content={selectedBlog?.metadescription || ""}></meta>
				<meta name="keywords" content="material handling, equipment manufacturing, industry trends, tips, insights, blog articles, informative content, industry updates, Aerial Work Platform, Ladders, Chemical Pumps & Accessories, Cranes & Lifting Accessories, Dock Levellers & Dock Ramp, Drum Equipments, Industrial Stirrer, Fuel Pumps Meters & Accessories, Goods Lift, Hydraulic Scissor Lift Platform, Insect Killer Machine, Hand Trucks, Order Picker Trucks, Oil Pumps Meters & Accessories, Pallet Trucks, Polyurethane Wheels & Rollers, Wheels & Casters, Stackers, Industrial Springs, Metal Pallets, Gas Cylinder Cart"></meta>
				<meta http-equiv="Content-Type" content="text/html; charset=utf-8"></meta>
				<meta property="og:type" content="website"></meta>
				<meta property="og:url" content={"https://kijeka.com/blog/" + (selectedBlog?.blogLink || "")}></meta>
				<meta property="og:title" content={selectedBlog?.title || "Kijeka Blog"}></meta>
				<meta property="og:description" content={selectedBlog?.metadescription || ""}></meta>
				<meta property="og:image" content="/static/images/KijekaMeta.webp"></meta>
				<meta property="twitter:card" content="summary_large_image"></meta>
				<meta property="twitter:url" content={"https://kijeka.com/blog/" + (selectedBlog?.blogLink || "")}></meta>
				<meta property="twitter:title" content={selectedBlog?.title || "Kijeka Blog"}></meta>
				<meta property="twitter:description" content={selectedBlog?.metadescription || ""}></meta>
				<meta property="twitter:image" content="/static/images/KijekaMeta.webp"></meta>
				<link rel="canonical" href={"https://kijeka.com/blog/" + (selectedBlog?.blogLink || "")} />
			</Helmet>
			<ShareProduct />
			<div className="relative flex justify-start items-center group lg:px-10 px-4 lg:mt-24 mt-20">
				<div className="h-14 w-1.5 max-md:h-12 bg-kijeka-blue mr-[1rem] origin-left group-hover:w-[15rem] duration-300 group"></div>
				<p className="text-2xl max-sm:text-[22px] absolute font-bold text-kijeka-blue ml-[1rem] group-hover:text-white group-hover:translate-x-5 duration-300">Latest News</p>
			</div>
			<div className="lg:flex flex-sm:grid lg:pl-[30px] px-4 sm:grid-cols-4 max-sm:overflow-hidden lg:mt-10 mt-5">
				<div className="col-span-1">
					<BlogsList listdData={category} />
				</div>
				<div className="col-span-3 lg:pl-[8%] lg:pr-[4.43%] ">
					{error ? (
						<div className="flex flex-col items-center justify-center p-10 border-2 border-dashed border-red-100 rounded-xl bg-red-50/30">
							<div className="text-red-500 mb-4 text-4xl">⚠️</div>
							<p className="text-red-600 font-medium text-center">{error}</p>
							<button 
								onClick={() => window.location.reload()} 
								className="mt-6 px-6 py-2 bg-kijeka-blue text-white rounded-full hover:bg-opacity-90 transition-all shadow-md"
							>
								Retry Loading Blogs
							</button>
						</div>
					) : (
						<BlogItemsDisplay readEnabled={readEnabled} setReadEnabled={setReadEnabled} listdData={listdData} blogData={selectedBlog} />
					)}
				</div>
			</div>
			<div className="flex lg:ml-[60px] px-4 lg:px-0 py-[46px]">
				<div className="w-[6px] bg-[#004B95] hover:w-[240px] cursor-pointer  transition-all duration-500 font-poppins font-bold text-[#004B95] text-[28px] leading-[42px] hover:text-[white] hover:translate-x-1 gap-2 ">
					<p className="pl-[30px]">Recent</p>
				</div>
			</div>
			<div className="grid md:grid-cols-2 lg:grid-cols-2 xl:grid-cols-3 grid-cols-1 gap-[22px] lg:px-[52px] px-4 mb-10">
				{blogs && blogs.map((item, index) => {
					return (
						<Link
							key={index}
							to={"/blog/" + blogs[index]?.["blogLink"]}
							preload="intent"
							aria-label={`Read more about ${item?.title}`}
							onClick={() => {
								setSelectedBlog(blogs[index]);
								setReadEnabled(false);
								window.scrollTo(0, 0);
							}}
						>
							<BlogCategoriesCard data={item} />
						</Link>
					);
				})}
			</div>
		</>
	);
};

export default Blog;

